/**
 * Turns the data `describe.mjs` makes into the Markdown pages in docs/reference/content-types/
 * (#714). Pure functions: the same data always gives the same text, with nothing sorted by time or
 * machine. The generator formats the result with Prettier before it writes or compares it.
 */

export const GENERATED_NOTICE =
  '> Generated by `npm run docs:generate` from the loaded Payload config (`src/payload.config.ts`). Do not edit by hand: change the config, then run `npm run docs:generate`.'

/** The longest a page may be, as in `AGENTS.md`: a longer one is split. */
export const PAGE_LINE_LIMIT = 250

/**
 * Text for a Markdown table cell. Backslashes are escaped first, so one in the text can't cancel
 * the escape of the pipe after it; then pipes; then line breaks become spaces.
 */
const cell = (text) =>
  String(text)
    .replace(/\\/g, '\\\\')
    .replace(/\|/g, '\\|')
    .replace(/\s*\n\s*/g, ' ')

const code = (text) => (text ? `\`${cell(text)}\`` : '')

/** A name in a table: inline functions have no name worth quoting. */
const nameCell = (name) => (name === 'inline' ? 'inline' : code(name))

/** A file in a table: a path is code, the other answers are plain words. */
const fileCell = (file) => (file.startsWith('src/') ? code(file) : cell(file))

function table(header, rows) {
  const line = (cells) => `| ${cells.join(' | ')} |`
  return [line(header), line(header.map(() => '---')), ...rows.map(line)].join('\n')
}

const slugify = (text) =>
  text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '')

export function renderFieldTable(rows) {
  return table(
    ['Field', 'Type', 'Required', 'Target or options', 'Notes'],
    rows.map((row) => [
      code(row.path),
      cell(row.type),
      row.required,
      cell(row.detail),
      cell([...row.notes, ...row.access.map((access) => `access ${access}`)].join('; ')),
    ]),
  )
}

export function renderAccess(access) {
  if (access.length === 0) {
    return 'No access function is set, so Payload’s default applies: any signed-in user.'
  }
  return table(
    ['Operation', 'Function', 'Defined in'],
    access.map((a) => [a.operation, nameCell(a.name), fileCell(a.file)]),
  )
}

export function renderHooks(hooks) {
  if (hooks.length === 0) return 'None.'
  return table(
    ['Phase', 'Function', 'Defined in'],
    hooks.map((h) => [h.phase, nameCell(h.name), fileCell(h.file)]),
  )
}

function renderFieldHooks(rows) {
  const hooks = rows.flatMap((row) => row.hooks.map((hook) => ({ path: row.path, ...hook })))
  if (hooks.length === 0) return ''
  return table(
    ['Field', 'Phase', 'Function', 'Defined in'],
    hooks.map((h) => [code(h.path), h.phase, nameCell(h.name), fileCell(h.file)]),
  )
}

const settingsTable = (pairs) =>
  table(
    ['Setting', 'Value'],
    pairs.map(([key, value]) => [code(key), cell(value)]),
  )

const block = (...parts) => parts.filter(Boolean).join('\n\n')

const heading = (level, text) => `${'#'.repeat(level)} ${text}`

function fieldsWithHooks(rows, level) {
  const hooks = renderFieldHooks(rows)
  return block(renderFieldTable(rows), hooks && heading(level, 'Field hooks'), hooks)
}

const sections = (rows) => [...new Set(rows.map((row) => row.section).filter(Boolean))]

const sectionFile = (model, section) => `${model.slug}--${slugify(section)}.md`

/**
 * The body of one content type below its heading, whose subheadings are one level deeper than
 * `level`. With `split`, the fields of named sections are left out for pages of their own.
 */
function renderBody(model, level, { split = false } = {}) {
  const h = (text) => heading(level + 1, text)
  const facts = [
    `- Kind: ${model.kind}`,
    model.purpose && `- Purpose: ${cell(model.purpose)}`,
    ...model.versions.map((line) => `- ${line}`),
  ].filter(Boolean)
  const own = split ? model.fields.filter((row) => !row.section) : model.fields
  const parts = [
    facts.join('\n'),
    h('Access'),
    renderAccess(model.access),
    h('Hooks'),
    renderHooks(model.hooks),
  ]
  if (model.auth.length > 0) parts.push(h('Sign-in settings'), settingsTable(model.auth))
  if (model.upload.length > 0) parts.push(h('Upload settings'), settingsTable(model.upload))
  parts.push(h('Fields'))
  parts.push(own.length > 0 ? fieldsWithHooks(own, level + 2) : split ? '' : 'None.')
  if (split) {
    const links = sections(model.fields).map((section) => {
      const count = model.fields.filter((row) => row.section === section).length
      return `- [${section}](${sectionFile(model, section)}): ${count} fields`
    })
    parts.push('The rest of the fields are on their own pages:', links.join('\n'))
  }
  return block(...parts)
}

const titleOf = (model) => `${model.title} (${code(model.slug)})`

function renderPage(model, options) {
  return `${block(GENERATED_NOTICE, heading(1, titleOf(model)), renderBody(model, 1, options))}\n`
}

function renderSectionPage(model, section) {
  const rows = model.fields.filter((row) => row.section === section)
  const back = `Part of [${model.title}](${model.slug}.md).`
  return `${block(GENERATED_NOTICE, heading(1, `${titleOf(model)}: ${section}`), back, fieldsWithHooks(rows, 2))}\n`
}

const lineCount = (text) => text.trimEnd().split('\n').length

function renderInternalPage(models) {
  const intro =
    'Payload’s own collections and globals, which hold its queue, locks, saved settings and migration record. They are in the loaded config, so they are described here, on one page.'
  const bodies = models.map((model) => block(heading(2, code(model.slug)), renderBody(model, 2)))
  return `${block(GENERATED_NOTICE, heading(1, 'Payload internal content types'), intro, ...bodies)}\n`
}

function renderReadme(entries) {
  const intro =
    'One page for every collection and global in the loaded Payload config, plugins included. Generated. What each type is for, why the model is shaped this way, its relations and what each hook is for are in [`docs/architecture/data-model.md`](../../architecture/data-model.md). “Defined in” is the file the function was written in, or the package for Payload’s and the plugins’ own; `inline` in the Function column is an anonymous function.'
  const rows = entries.map((entry) => [
    `[${code(entry.slug)}](${entry.link})`,
    entry.kind,
    cell(entry.summary),
    entry.drafts,
  ])
  return `${block(GENERATED_NOTICE, heading(1, 'Content types'), intro, table(['Page', 'Kind', 'Description in the config', 'Drafts'], rows))}\n`
}

/**
 * Builds every file: a page per content type (split by section when it is over the line limit),
 * one shared page for the internal ones, and the README. Returns a Map of file name to text,
 * sorted by name. Throws when a file is still over the limit, so a split is never silent.
 */
export function buildPages(models, { internal = [], limit = PAGE_LINE_LIMIT } = {}) {
  const sorted = [...models].sort((a, b) => a.slug.localeCompare(b.slug))
  const files = new Map()
  const entries = []
  for (const model of sorted.filter((m) => !internal.includes(m.slug))) {
    const whole = renderPage(model, {})
    if (lineCount(whole) <= limit) {
      files.set(`${model.slug}.md`, whole)
    } else {
      files.set(`${model.slug}.md`, renderPage(model, { split: true }))
      for (const section of sections(model.fields)) {
        files.set(sectionFile(model, section), renderSectionPage(model, section))
      }
    }
    entries.push({ model, link: `${model.slug}.md` })
  }
  const shared = sorted.filter((m) => internal.includes(m.slug))
  if (shared.length > 0) {
    files.set('payload-internal.md', renderInternalPage(shared))
    for (const model of shared) {
      entries.push({ model, link: `payload-internal.md#${model.slug}` })
    }
  }
  files.set(
    'README.md',
    renderReadme(
      entries
        .map(({ model, link }) => ({
          slug: model.slug,
          link,
          kind: model.kind,
          summary: model.purpose.split(/(?<=\.)\s/)[0],
          drafts: model.versions[0].startsWith('Drafts: yes') ? 'yes' : 'no',
        }))
        .sort((a, b) => a.slug.localeCompare(b.slug)),
    ),
  )
  for (const [file, text] of files) {
    if (lineCount(text) > limit) {
      throw new Error(`${file} has ${lineCount(text)} lines, over the limit of ${limit}`)
    }
  }
  return new Map([...files].sort(([a], [b]) => a.localeCompare(b)))
}
